<script lang="ts">
  import { onMount } from 'svelte';import { resolve } from '$app/paths';import Navbar from '../../lib/ui/Navbar.svelte';import { session } from '../../lib/auth/session';import type { Work } from '../../lib/catalog/api';
  let lists=$state<{id:string;name:string}[]>([]);let selected=$state('');let items=$state<Work[]>([]);let name=$state('À regarder');let error=$state('');let busy=$state(false);
  async function load(){const response=await fetch('/api/v1/lists');if(!response.ok)throw new Error('Listes indisponibles.');lists=(await response.json()).lists;}
  async function show(){error='';try{const response=await fetch(`/api/v1/lists/${selected}`);if(!response.ok)throw new Error('Liste indisponible.');items=(await response.json()).items;}catch(cause){error=cause instanceof Error?cause.message:'Erreur';}}
  async function mutate(path:string,method:string,body?:unknown){error='';busy=true;try{const response=await fetch(path,{method,headers:{'content-type':'application/json','x-csrf-token':$session?.csrfToken??''},body:body?JSON.stringify(body):undefined});if(!response.ok)throw new Error('Modification impossible.');await load();return true;}catch(cause){error=cause instanceof Error?cause.message:'Erreur';return false;}finally{busy=false;}}
  onMount(()=>{void load().catch(cause=>error=cause.message);});
</script>
<Navbar section="lists" /><main><h1>Mes listes</h1><form onsubmit={event=>{event.preventDefault();void mutate('/api/v1/lists','POST',{name});}}><label>Nouvelle liste<input required maxlength="100" bind:value={name} /></label><button disabled={busy}>Créer</button></form><label>Choisir une liste<select bind:value={selected} onchange={show}><option value="">Choisir</option>{#each lists as list(list.id)}<option value={list.id}>{list.name}</option>{/each}</select></label>{#if selected}<button disabled={busy} onclick={async()=>{if(await mutate(`/api/v1/lists/${selected}`,'DELETE')){selected='';items=[];}}}>Supprimer cette liste</button>{/if}
{#each items as work(work.id)}<article><a href={resolve(`${work.kind==='series'?'series':'films'}/?work=${encodeURIComponent(work.id)}`)}>{work.title}</a><button disabled={busy} onclick={async()=>{if(await mutate(`/api/v1/lists/${selected}/items/${work.id}`,'DELETE'))await show();}}>Retirer de la liste</button></article>{/each}{#if error}<p role="alert">{error}</p>{/if}</main>
<style>main { max-width:1000px;margin:auto;padding:24px; } form,label,article { display:flex;gap:12px;align-items:center;flex-wrap:wrap;margin:16px 0; } article { justify-content:space-between;padding:14px;border-bottom:1px solid var(--color-line); } input,select,button { padding:10px;background:var(--color-surface);color:var(--color-text);border:1px solid var(--color-line);border-radius:8px; } a { color:var(--color-accent); } </style>
